        start: a,
        end: addDays(a, 7),
        kind: 'week',
        label: D.fmtDate(a, 'M/D'),
        caption: D.fmtDate(a, 'M月D日') + '–' + D.fmtDate(addDays(a, 6), 'M月D日')
