  const y0 = startOfYear(first)
  const years = n.getFullYear() - f.getFullYear() + 1
  for (let i = 0; i < years; i++) {
    const a = addYearsMs(y0, i)
    out.push({ start: a, end: addYearsMs(a, 1), kind: 'year', label: D.fmtDate(a, 'YYYY'), caption: D.fmtDate(a, 'YYYY年') })
  }
