    if (typeof ev.dose === 'string' && ev.dose) eventRows.push({ key: 'dose', title: '剂量', value: ev.dose, sub: '' })
    if (typeof ev.costFen === 'number' && isFinite(ev.costFen)) eventRows.push({ key: 'cost', title: '费用', value: F.fmtMoney(ev.costFen), sub: '' })
