    photos: photos,
    multiPhoto: photos.length > 1,
    metricRows: metricRows,
    statusRows: statusRows,
    eventTitle: EVENT_TITLE[rec.kind] || '事件详情',
    eventRows: eventRows,
    behaviors: behaviors,
    hasRedFlag: flags.length > 0,
    redFlagText: flags.join('、'),
    clinicPhone: clinicPhone,
    callText: clinicName ? '联系 ' + clinicName : '联系医院',
    note: typeof rec.note === 'string' ? rec.note.trim() : '',
    footText: footText,
