// ---------- 提要 ----------

function weightHighlight(pet, series, weekStart) {
  const pts = series || []
  if (!pts.length) return null
  const last = pts[pts.length - 1]
  if (last.t < weekStart) return null
  const name = petName(pet)
  let base = null
  for (let i = pts.length - 1; i >= 0; i--) {
    if (pts[i].t < weekStart) {
      base = pts[i]
      break
    }
  }
  let when = ''
  if (base) {
    when = base.t >= weekStart - 14 * DAY ? '上周' : D.fmtDate(base.t, 'M月D日')
  } else {
    // no earlier weight: compare within the 7 days
    let first = null
    for (let i = 0; i < pts.length; i++) {
      if (pts[i].t >= weekStart) {
        first = pts[i]
        break
      }
    }
    if (first && first !== last) base = first
  }
  const sc = weightScale(pet.species, Math.max(last.v, base ? base.v : 0))
  const nowText = F.fmtNumber(last.v / sc.div, sc.digits) + ' ' + sc.unit
  const hl = {
    key: 'weight',
    icon: 'scale',
    color: 'cat-body',
    cls: 'cat-body',
    title: '体重',
    text: '',
    tag: '',
    chart: null,
    url: '/pages/metric/metric?key=weightG&petId=' + pet._id
  }
  if (!base) {
    hl.text = name + '最近一次称重为 ' + nowText + '。'
    return hl
  }
  const delta = last.v - base.v
  const absText = F.fmtNumber(Math.abs(delta) / sc.div, sc.digits)
  if (!absText || absText === '0') {
    hl.text = when
      ? name + '的体重与' + when + '持平，目前为 ' + nowText + '。'
      : '过去 7 天中，' + name + '的体重保持在 ' + nowText + '。'
    hl.tag = '持平'
  } else {
    const verb = delta > 0 ? '增加了 ' : '减少了 '
    hl.text = when
      ? name + '的体重比' + when + verb + absText + ' ' + sc.unit + '，目前为 ' + nowText + '。'
      : '过去 7 天中，' + name + '的体重' + verb + absText + ' ' + sc.unit + '。'
    hl.tag = (delta > 0 ? '↑' : '↓') + absText + ' ' + sc.unit
  }
  const recent = pts.slice(-8)
  if (recent.length >= 2) {
    hl.chart = {
      type: 'line',
      points: recent.map((p) => ({ t: p.t, v: round(p.v / sc.div, sc.digits), label: D.fmtDate(p.t, 'M/D') }))
    }
  }
  return hl
}

function activityHighlight(pet, week, days) {
  const withData = days.filter((d) => d.v !== null)
  if (!withData.length) return null
  const name = petName(pet)
  const avg = week && typeof week.activityAvg === 'number'
    ? week.activityAvg
    : Math.round(withData.reduce((a, d) => a + d.v, 0) / withData.length)
  let text
  if (withData.length >= 4) {
    text = '过去 7 天中，' + name + '平均每天活动 ' + avg + ' 分钟。'
  } else {
    text = '过去 7 天中，' + name + '有 ' + withData.length + ' 天记录了活动，平均每天 ' + avg + ' 分钟。'
  }
  return {
    key: 'activity',
    icon: 'flame',
    color: 'cat-activity',
    cls: 'cat-activity',
    title: '活动',
    text: text,
    tag: '',
    chart: { type: 'bar', points: days },
    url: '/pages/metric/metric?key=activityMin&petId=' + pet._id
  }
}

function recordsHighlight(pet, week) {
  if (!week || !week.recordCount) return null
  const name = petName(pet)
  let text = '过去 7 天中，你为' + name + '记录了 ' + week.recordCount + ' 次'
  text += week.photoCount ? '，拍了 ' + week.photoCount + ' 张照片。' : '。'
  return {
    key: 'records',
    icon: 'doc',
    color: 'tint',
    cls: '',
    title: '记录',
    text: text,
    tag: '',
    chart: null,
    tab: '/pages/timeline/timeline',
    segment: 0
  }
}

function moodHighlight(pet, week) {
  const code = week && week.moodTop
  let mood = null
  C.MOODS.forEach((m) => { if (m.code === code) mood = m })
  if (!mood) return null
  return {
    key: 'mood',
    icon: 'smile',
    color: 'cat-mood',
    cls: 'cat-mood',
    title: '心情',
    text: '过去 7 天中，' + petName(pet) + '最常见的心情是“' + mood.label + '”。',
    tag: '',
    chart: null,
    plain: true // nothing to open
  }
}

// ---------- 那年今天 / 品种小传 / 所有数据 ----------

function memoriesVM(pet, records, now) {
  const thisYear = new Date(now).getFullYear()
  const byYear = {}
  const out = []
  ;(records || []).forEach((r) => {
    const y = new Date(r.occurredAt).getFullYear()
    if (byYear[y]) return // one per year: the newest that day
    byYear[y] = true
    const kind = C.KIND_MAP[r.kind] || C.KIND_MAP.daily
    const age = pet.birthday ? D.ageAtText(pet.birthday, r.occurredAt, pet.birthdayPrecision) : ''
    out.push({
      id: r._id,
      when: (thisYear - y) + ' 年前的今天',
      title: F.recordTitle(r, pet.species),
      sub: D.fmtDate(r.occurredAt, 'YYYY年M月D日') + (age ? ' · ' + age : ''),
      photo: Array.isArray(r.photos) && r.photos.length ? r.photos[0] : '',
      icon: kind.icon,
      color: kind.color
    })
  })
  return out.slice(0, 3)
}

function factsLore(data, pet) {
  const lore = data && data.lore
  const body = lore && String(lore.summary || '').trim()
  if (!body) return null
  const src = lore.source ? '资料来源：' + lore.source : ''
  return {
    kicker: String(pet.breed || '').trim() || speciesOf(pet).label,
    title: String(lore.title || '').trim() || String(pet.breed || '').trim() || '品种小传',
    body: body,
    source: src,
    ai: false
  }
}

function reportLore(reports, pet) {
  const list = reports || []
  for (let i = 0; i < list.length; i++) {
    const r = list[i]
    if (r.status !== 'done' || r.blocked || r.secChecked !== true) continue
    const bl = r.content && r.content.breedLore
    const story = bl && String(bl.story || '').trim()
    if (!story) continue
    return {
      kicker: String(pet.breed || '').trim() || speciesOf(pet).label,
      title: String(bl.title || '').trim() || '品种小传',
      body: story,
      source: '摘自 ' + (weekRangeText(r.weekStart, r.weekEnd) || '') + ' 的周报',
      ai: true
    }
  }
  return null
}

function metricRows(pet, latest, now) {
  return C.METRICS.map((m) => {
    const L = latest && latest[m.key]
    return {
      key: m.key,
      icon: m.icon,
      color: m.color,
      label: shortLabel(m.label),
      value: L ? joinValue(F.fmtMetric(m.key, L.v, pet.species)) : '暂无',
      sub: L ? D.relativeDay(L.t, now) : ''
    }
  })
}

