    collapsed: false,
    nav: null,
    segments: SEGMENTS,
    segment: 0,
    listLoading: true,
    skeleton: [0, 1, 2, 3],
    groups: [],
    footText: '',
    hint: false,
    memorial: false,
    memorialText: '',
