function compress(src) {
  return new Promise((resolve) => {
    wx.compressImage({
      src,
      quality: 80,
      success: (res) => resolve((res && res.tempFilePath) || src),
      fail: () => resolve(src)
    })
  })
}

// Existing cloud:// fileIDs are passed through unchanged.
async function uploadImages(tempFilePaths, petId) {
  const list = (tempFilePaths || []).filter(Boolean)
  if (!list.length) return []
  const ts = Date.now()
  const yyyy = new Date(ts).getFullYear()
  const folder = petId || 'unsorted'
  const fresh = []
  let ids
  try {
    ids = await Promise.all(
      list.map((path, i) => {
        if (String(path).indexOf('cloud://') === 0) return Promise.resolve(path)
        return compress(path)
          .then((filePath) => wx.cloud.uploadFile({ cloudPath: `pets/${folder}/${yyyy}/${ts}-${i}.jpg`, filePath }))
          .then((res) => {
            fresh.push(res.fileID)
            return res.fileID
          })
      })
    )
  } catch (err) {
    if (fresh.length) deleteFiles(fresh)
    const e = new Error('图片上传失败，请检查网络后重试')
    e.cause = err
    throw e
  }
  fresh.forEach((fileID) => {
    callFn('contentCheck', { action: 'image', fileID, petId: petId || '' }).catch((err) => {
      console.warn('[api] contentCheck image', err)
    })
  })
  return ids
}

async function checkText(text) {
  const t = String(text || '').trim()
  if (!t) return { pass: true }
  try {
    const r = (await callFn('contentCheck', { action: 'text', text: t })) || {}
    if (r.pass === false) return { pass: false, reason: '内容可能包含不适宜的信息，请修改后再保存' }
    return { pass: true }
  } catch (err) {
    console.warn('[api] checkText failed, fail-open', err)
    return { pass: true }
  }
}

