  manualPet: (openid, petId, day) => 'mp_' + openid + '_' + petId + '_' + day,
  manualOwner: (openid, day) => 'mo_' + openid + '_' + day,
  weeklyOwner: (openid, weekStart) => 'wo_' + openid + '_' + weekStart,
  weeklyScan: (weekStart) => 'ws_' + weekStart,
