// Pure helpers for contentCheck (SPEC §6.5).

const CHUNK = 2500
const MAX_TEXT = 10000
const RANK = { pass: 0, error: 0, review: 1, risky: 2 }

// Split by code points into chunks of at most `size` characters.
function chunkText(text, size) {
  const n = size || CHUNK
  const a = Array.from(String(text || ''))
  const out = []
  for (let i = 0; i < a.length; i += n) out.push(a.slice(i, i + n).join(''))
  return out.filter((s) => s.trim())
}

function clipText(text, max) {
  const a = Array.from(String(text || ''))
  return a.length > (max || MAX_TEXT) ? a.slice(0, max || MAX_TEXT).join('') : a.join('')
}

// All human-readable strings of a report's content, newline-joined.
function reportText(content) {
  const c = content || {}
  const parts = [c.headline, c.summary]
  ;(c.highlights || []).forEach((h) => h && parts.push(h.title, h.text))
  if (c.health) parts.push(c.health.text)
  ;(c.careTips || []).forEach((t) => parts.push(t))
  if (c.breedLore) parts.push(c.breedLore.title, c.breedLore.story)
  ;(c.scienceFacts || []).forEach((f) => f && parts.push(f.fact, f.source))
  ;(c.nextWeek || []).forEach((t) => parts.push(t))
  return parts.filter((s) => typeof s === 'string' && s.trim()).join('\n')
}

// Worst suggestion wins: risky > review > pass.
function worst(results) {
  let best = { suggest: 'pass', label: 100 }
  for (const r of results || []) {
    if (!r) continue
    const s = r.suggest || 'pass'
    if ((RANK[s] || 0) > (RANK[best.suggest] || 0)) best = { suggest: s, label: r.label }
  }
  return best
}

