function buildPalette(hue, hueText, base) {
  const out = {};
  HUES.forEach(function (h) {
    out[h] = hue[h];
    out[h + '-text'] = hueText[h];
  });
  Object.keys(CATEGORY_HUE).forEach(function (token) {
    const h = CATEGORY_HUE[token];
    out[token] = hue[h];
    out[token + '-text'] = hueText[h];
  });
  Object.keys(base).forEach(function (k) { out[k] = base[k]; });
  return out;
}

