// Calendar math in Asia/Shanghai (fixed UTC+8, no DST). Pure offset arithmetic:
// results never depend on the process time zone.
// NOTE: cloudfunctions/reportEnqueue/lib/week.js must stay byte-identical to this file.

const OFFSET_MS = 8 * 3600 * 1000
const DAY_MS = 24 * 3600 * 1000

function pad(n) {
  return n < 10 ? '0' + n : String(n)
}

// Shifted Date whose UTC fields read as Shanghai wall-clock fields.
function sh(ms) {
  return new Date(ms + OFFSET_MS)
}

// 'YYYY-MM-DD' of the Shanghai calendar day containing ms.
function ymd(ms) {
  const d = sh(ms)
  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate())
}

// ms of 00:00 Shanghai on the given 'YYYY-MM-DD'.
function ymdToMs(str) {
  const m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(String(str || '').trim())
  if (!m) return NaN
  return Date.UTC(+m[1], +m[2] - 1, +m[3]) - OFFSET_MS
}

// ms of 00:00 Shanghai of the day containing ms.
function startOfDay(ms) {
  return Math.floor((ms + OFFSET_MS) / DAY_MS) * DAY_MS - OFFSET_MS
}

function addDaysYmd(str, n) {
  return ymd(ymdToMs(str) + n * DAY_MS)
}

// 0 = Monday … 6 = Sunday (Shanghai).
function weekday(ms) {
  return (sh(ms).getUTCDay() + 6) % 7
}

// ms of Monday 00:00 Shanghai of the week containing ms.
function weekStartMs(ms) {
  return startOfDay(ms) - weekday(ms) * DAY_MS
}

function rangeFromMs(startMs, days) {
  const endExclusiveMs = startMs + days * DAY_MS
  return {
    weekStart: ymd(startMs),
    weekEnd: ymd(endExclusiveMs - 1),
    startMs,
    endExclusiveMs,
  }
}

// Previous full Monday–Sunday week relative to nowMs.
function lastFullWeek(nowMs) {
  return rangeFromMs(weekStartMs(nowMs) - 7 * DAY_MS, 7)
}

// The 7 calendar days ending today (inclusive), Shanghai.
function last7Days(nowMs) {
  return rangeFromMs(startOfDay(nowMs) - 6 * DAY_MS, 7)
}

// Range for stored inclusive 'YYYY-MM-DD' bounds.
function rangeFromYmd(weekStart, weekEnd) {
  const startMs = ymdToMs(weekStart)
  const endExclusiveMs = ymdToMs(weekEnd) + DAY_MS
  return { weekStart, weekEnd, startMs, endExclusiveMs }
}

// ISO week key 'YYYY-Www' for a ms or 'YYYY-MM-DD'.
function weekKey(msOrYmd) {
  const ms = typeof msOrYmd === 'string' ? ymdToMs(msOrYmd) : msOrYmd
  const d = sh(ms)
  const day = (d.getUTCDay() + 6) % 7
  // Thursday of this ISO week decides the year.
  const thu = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) + (3 - day) * DAY_MS
  const t = new Date(thu)
  const year = t.getUTCFullYear()
  const jan1 = Date.UTC(year, 0, 1)
  const week = Math.floor((thu - jan1) / DAY_MS / 7) + 1
  return year + '-W' + pad(week)
}

function monthOf(ms) {
  return sh(ms).getUTCMonth() + 1
}

function yearOf(ms) {
  return sh(ms).getUTCFullYear()
}

// Meteorological season for the northern hemisphere (China).
function seasonOf(ms) {
  const m = monthOf(ms)
  if (m >= 3 && m <= 5) return '春季'
  if (m >= 6 && m <= 8) return '夏季'
  if (m >= 9 && m <= 11) return '秋季'
  return '冬季'
}

// 'YYYY年M月D日'
function zhDate(ms) {
  const d = sh(ms)
  return d.getUTCFullYear() + '年' + (d.getUTCMonth() + 1) + '月' + d.getUTCDate() + '日'
}

// 'M月D日'
function zhMonthDay(msOrYmd) {
  const ms = typeof msOrYmd === 'string' ? ymdToMs(msOrYmd) : msOrYmd
  const d = sh(ms)
  return d.getUTCMonth() + 1 + '月' + d.getUTCDate() + '日'
}

// 'M月D日 HH:mm'
function zhMonthDayTime(ms) {
  const d = sh(ms)
  return d.getUTCMonth() + 1 + '月' + d.getUTCDate() + '日 ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes())
}

// '10月5日–10月11日'
function zhRange(weekStart, weekEnd) {
  return zhMonthDay(weekStart) + '–' + zhMonthDay(weekEnd)
}

module.exports = {
  OFFSET_MS,
  DAY_MS,
  ymd,
  ymdToMs,
  startOfDay,
  addDaysYmd,
  weekday,
  weekStartMs,
  lastFullWeek,
  last7Days,
  rangeFromYmd,
  weekKey,
  monthOf,
  yearOf,
  seasonOf,
  zhDate,
  zhMonthDay,
  zhMonthDayTime,
  zhRange,
}

