const MAX_PAGES = 10
const BASELINE_DAYS = 28
const BREED_FACTS_TIMEOUT_MS = 20000
const QWEN_TIMEOUT_MS = 120000
const PARSE_RETRY_MIN_LEFT_MS = 150000
