      const slot = await takeBudget(Date.now())
      if (!slot) {
        outOfBudget = true // jobs stay queued (no attempt spent) until tomorrow's budget
        return null
      }
      const job = await tryClaim(doc, Date.now())
      if (job) return job
      await slot.release()
