  if (!reportId || typeof reportId !== 'string') return { error: 'BAD_REQUEST', message: '缺少周报 ID' }
  const doc = await getDoc(REPORTS, reportId)
  if (!doc) return { error: 'NOT_FOUND', message: '周报不存在' }
  if (doc._openid !== openid) return { error: 'FORBIDDEN', message: '无权操作该周报' }
  const now = Date.now()
  if (doc.status === 'done') return { status: 'done' }
