const BEHAVIOR_GROUP = {
  dog: 'dog', cat: 'cat', bird: 'bird',
  rabbit: 'small', hamster: 'small', guinea_pig: 'small',
  reptile: 'reptile', fish: 'fish'
};

// behaviorsFor(species) → species list followed by common items not already present.
function behaviorsFor(species) {
  const group = BEHAVIOR_GROUP[species];
  const base = group ? BEHAVIORS[group] : [];
  const seen = {};
  const out = [];
  base.concat(BEHAVIORS.common).forEach(function (item) {
    if (seen[item.code]) return;
    seen[item.code] = true;
    out.push(item);
  });
  return out;
}

